CREATE OR REPLACE FUNCTION public.client_gym_content(g uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF auth.uid() IS NULL OR NOT (EXISTS(SELECT 1 FROM public.client_gym_links WHERE user_id=auth.uid() AND gym_id=g) OR EXISTS(SELECT 1 FROM public.gym_records WHERE gym_id=g AND kind='members' AND client_id=auth.uid()) OR EXISTS(SELECT 1 FROM public.user_roles WHERE gym_id=g AND user_id=auth.uid())) THEN RAISE EXCEPTION 'Join this gym to view its client pages'; END IF; SELECT jsonb_build_object('workouts',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',data->>'name','trainer',data->>'trainer','notes',data->>'notes','exercises',data->'exercises')) FROM public.gym_records WHERE gym_id=g AND kind='workouts'),'[]'::jsonb),'products',coalesce((SELECT jsonb_agg(jsonb_build_object('name',data->>'name','price',data->'price','image',data->>'image')) FROM public.gym_records WHERE gym_id=g AND kind='products'),'[]'::jsonb),'trainers',coalesce((SELECT jsonb_agg(jsonb_build_object('name',data->>'name','specialty',data->>'specialty','bio',data->>'bio','image',data->>'image')) FROM public.gym_records WHERE gym_id=g AND kind='trainers'),'[]'::jsonb)) INTO result; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.prevent_profile_identity_change() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.member_id IS DISTINCT FROM OLD.member_id OR NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'Permanent member identity cannot change'; END IF; IF auth.uid() IS NOT NULL AND (NEW.account_type IS DISTINCT FROM OLD.account_type OR NEW.email IS DISTINCT FROM OLD.email) THEN RAISE EXCEPTION 'Identity fields can only be changed through authentication'; END IF; RETURN NEW; END $$;